// Smart DCA Logic
const status = $('Check System Status').first().json;
const ticker = $('Get BTC Price').first().json;
const ohlc = $('Get 20-Day History').first().json;

// Safety check
if (status.trading_halted) {
  return [{ json: { action: 'skip', reason: 'Trading halted: ' + status.halt_reason } }];
}

// Get current price
const currentPrice = ticker.tickers?.XXBTZUSD?.price || 0;
if (!currentPrice) {
  return [{ json: { action: 'skip', reason: 'Could not get current price' } }];
}

// Calculate 20-day average from OHLC data
const candles = ohlc.ohlc || [];
let sum = 0;
let count = 0;
for (const candle of candles.slice(-20)) {
  const closePrice = parseFloat(candle[4]);
  if (closePrice) {
    sum += closePrice;
    count++;
  }
}
const avg20d = count > 0 ? sum / count : currentPrice;

// Calculate 24h change
const yesterdayClose = candles.length > 1 ? parseFloat(candles[candles.length - 2][4]) : currentPrice;
const change24h = ((currentPrice - yesterdayClose) / yesterdayClose) * 100;

// Position relative to average
const positionVsAvg = ((currentPrice - avg20d) / avg20d) * 100;

// Day of week (0 = Sunday)
const dayOfWeek = new Date().getDay();
const isSunday = dayOfWeek === 0;

// Decision logic
let action = 'skip';
let amount = 0;
let reason = '';

if (positionVsAvg < -5 && change24h < -3) {
  action = 'buy';
  amount = 15;
  reason = `Major dip: ${positionVsAvg.toFixed(1)}% below avg, ${change24h.toFixed(1)}% 24h drop`;
} else if (positionVsAvg < -3) {
  action = 'buy';
  amount = 12;
  reason = `Moderate dip: ${positionVsAvg.toFixed(1)}% below avg`;
} else if (isSunday) {
  action = 'buy';
  amount = 10;
  reason = `Sunday accumulation (${positionVsAvg.toFixed(1)}% vs avg)`;
} else {
  reason = `No opportunity: ${positionVsAvg.toFixed(1)}% vs avg`;
}

return [{
  json: {
    action,
    amount,
    reason,
    market_data: {
      current_price: currentPrice,
      avg_20d: avg20d,
      position_vs_avg_pct: positionVsAvg,
      change_24h_pct: change24h,
      is_sunday: isSunday
    },
    timestamp: new Date().toISOString()
  }
}];

const decision = $('Smart DCA Logic').first().json;
const result = $('Execute DCA Buy').first().json;
console.log('=== SMART DCA EXECUTED ===');
console.log('Amount: $' + decision.amount);
console.log('Reason: ' + decision.reason);
return [{ json: { success: true, type: 'smart_dca', amount: decision.amount, reason: decision.reason, result: result } }];

const decision = $('Smart DCA Logic').first().json;
console.log('=== SMART DCA SKIPPED ===');
console.log('Reason: ' + decision.reason);
return [{ json: { success: true, type: 'smart_dca_skip', reason: decision.reason } }];
